from pathlib import Path
import json,hashlib,sys
r=Path(__file__).resolve().parent
selected=sys.argv[1] if len(sys.argv)>1 else 'portrait_v2_maxcoverage'
roster=json.loads((r/'sources/roster_entry.json').read_text());old=json.loads((r/'manifest.json').read_text()) if (r/'manifest.json').exists() else {}
m=json.loads((r/'qa'/f'{selected}_metrics.json').read_text())
metrics=[json.loads(p.read_text()) for p in sorted((r/'qa').glob('portrait_v*_metrics.json'))]
manifest={'schema_version':1,'actor_id':roster['canonical_id'],'name':roster['name'],'date':'2026-10-15','selected_portrait':m['target']['path'],'selected_sha256':m['target']['sha256'],'status':old.get('status','awaiting_independent_visual_QA'),'generation_calls':len(list((r/'raw').glob('portrait_v*_raw_imagegen.png'))),'max_attempts':2,'native_authored':False,'native_pixel_approved':False,'runtime_integrated':False,'runtime_verified':False,'old_assets_preserved':True,'method':'Built-in imagegen substantive redraw. Entire-canvas NEAREST resize, binary alpha threshold 128 and no-dither 32-color quantization are explicitly derived candidates, not native authored pixel finals. No geometry redrawn by script.','color_budget_note':'At most 32 visible RGB colors is a temporary working ceiling, not proof of native pixel art.','source_manifest':'sources/source_manifest.json','spec_lock':'spec_lock.md','reproduction':['python derive_portrait.py','python export_maxcoverage.py portrait_v1','python export_maxcoverage.py portrait_v2',f'python finalize_manifest.py {selected}'],'assets':metrics,'prompts':[str(p.relative_to(r)) for p in sorted((r/'prompts').glob('*'))],'full_tool_returns':[str(p.relative_to(r)) for p in sorted((r/'tool_returns').glob('*.json'))],'author_visual_review':'qa/author_visual_review.json','independent_qa':old.get('independent_qa'),'previews':[f'previews/{selected}_1x_8x.png',f'previews/{selected}_8x.png'],'limitations':old.get('limitations',[]),'selection_note':old.get('selection_note','v2 supersedes v1 after one necessary imagegen revision; final independent QA pending.')}
manifest['files']=[{'path':str(p.relative_to(r)),'bytes':p.stat().st_size,'sha256':hashlib.sha256(p.read_bytes()).hexdigest()} for p in sorted(r.rglob('*')) if p.is_file() and p.name not in ('manifest.json','SHA256SUMS.txt')]
(r/'manifest.json').write_text(json.dumps(manifest,ensure_ascii=False,indent=2)+'\n')
(r/'SHA256SUMS.txt').write_text(''.join(hashlib.sha256(p.read_bytes()).hexdigest()+'  '+str(p.relative_to(r))+'\n' for p in sorted(r.rglob('*')) if p.is_file() and p.name!='SHA256SUMS.txt'))
print(json.dumps({'slug':roster['suggested_slug'],'selected':manifest['selected_portrait'],'sha256':manifest['selected_sha256'],'files':len(manifest['files']),'generation_calls':manifest['generation_calls']},ensure_ascii=False))
